process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs8', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs8 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS8'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP uxs8 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP uxs8 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd4=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&q=EU221Y`,{waitUntil:'networkidle',timeout:60000});
  await pause(1200);
  const a=await page.$('.pskat-t tbody tr[data-id] a.atv');
  if(a){
    await a.click(); await pause(3500);
    const kaina0=await page.evaluate(()=>document.querySelector('.kort-kaina input').value);
    out.kaina_pradine=kaina0;

    /* 1) keiciam kaina — ar atsiranda juosta */
    await page.evaluate(()=>{
      const i=document.querySelector('.kort-kaina input');
      i.focus(); i.value='7.77'; i.dispatchEvent(new Event('input',{bubbles:true}));
    });
    await pause(600);
    out.juosta=await page.evaluate(()=>{
      const j=document.getElementById('kort-saugoti');
      return j?{matoma:!j.hidden, tekstas:j.querySelector('.kiek').textContent.trim(),
                mygtukai:Array.prototype.map.call(j.querySelectorAll('button'),b=>b.textContent.trim())}:null;
    });
    let png=await page.screenshot(); out.s_juosta=await putRaw('screenshots/uxs8_juosta.png', png.toString('base64'),'uxs8 juosta');

    /* 2) ESC — ar klausia */
    await page.keyboard.press('Escape'); await pause(800);
    out.esc_klausia=await page.evaluate(()=>{
      const k=document.getElementById('ps-klausimas');
      return k?{matomas:!k.hidden, antraste:(k.querySelector('h3')||{}).textContent,
                laukai:(k.querySelector('.laukai')||{}).textContent,
                mygtukai:Array.prototype.map.call(k.querySelectorAll('.myg button'),b=>b.textContent.trim())}:null;
    });
    png=await page.screenshot(); out.s_klausimas=await putRaw('screenshots/uxs8_klausimas.png', png.toString('base64'),'uxs8 kl');
    await page.click('.ps-klausimas .k-grizti'); await pause(500);
    out.po_grizti=await page.evaluate(()=>{
      const k=document.getElementById('pskat-kort');
      return {kortele_atvira:!k.hidden, kaina:document.querySelector('.kort-kaina input').value};
    });

    /* 3) KITA PREKE sarase — ar klausia */
    const eiles=await page.$$('.pskat-t tbody tr[data-id] a.atv');
    out.eiluciu=eiles.length;
    await page.evaluate(()=>{ window.__navKlausta=false; });
    if(eiles.length>0){
      await eiles[0].click(); await pause(900);
      out.kita_preke_klausia=await page.evaluate(()=>{
        const k=document.getElementById('ps-klausimas'); return k?!k.hidden:null; });
    }

    /* 4) UZDARYTI NEISSAUGOJUS — ar atstato */
    if(out.kita_preke_klausia){
      await page.click('.ps-klausimas .k-prarasti'); await pause(2500);
      out.po_prarasti=await page.evaluate(()=>{
        const i=document.querySelector('.kort-kaina input');
        const j=document.getElementById('kort-saugoti');
        return {kaina:i?i.value:null, juosta_matoma:j?!j.hidden:null};
      });
    }

    /* 5) ISSAUGOTI IR UZDARYTI — realus irasymas, tada atstatom */
    await page.evaluate(()=>{
      const i=document.querySelector('.kort-kaina input');
      i.focus(); i.value='8.88'; i.dispatchEvent(new Event('input',{bubbles:true}));
    });
    await pause(500);
    await page.keyboard.press('Escape'); await pause(700);
    await page.click('.ps-klausimas .k-irasyti'); await pause(3000);
    out.po_issaugoti=await page.evaluate(()=>{
      const k=document.getElementById('ps-klausimas');
      const kort=document.getElementById('pskat-kort');
      return {klausimas_uzdarytas:k?k.hidden:null, kortele_uzdaryta:kort?kort.hidden:null};
    });
    /* atstatom pradine kaina */
    const a2=await page.$('.pskat-t tbody tr[data-id] a.atv');
    if(a2){ await a2.click(); await pause(3000);
      out.kaina_po_issaugojimo=await page.evaluate(()=>document.querySelector('.kort-kaina input').value);
      await page.evaluate((v)=>{
        const i=document.querySelector('.kort-kaina input');
        i.focus(); i.value=v; i.dispatchEvent(new Event('input',{bubbles:true}));
      }, kaina0);
      await pause(400);
      await page.click('#kort-saugoti .ks-irasyti'); await pause(3000);
      out.kaina_atstatyta=await page.evaluate(()=>document.querySelector('.kort-kaina input').value);
      out.juosta_po=await page.evaluate(()=>{ const j=document.getElementById('kort-saugoti'); return j?j.hidden:null; });
    }
  }
  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs8.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs8.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,700)}); });
